typedef unsigned char uint8;
typedef unsigned int uint32;

class color32
{
public:
	union
	{
		struct
		{
			uint8 b,g,r,a;
		} c;
		uint32 i;
	};

	color32(uint32 ic=0) : i(ic) {}
};

class FEMenu;

class FEMenuEntry
{
public:
	int entry_num;
	char layout[0x5c];

	virtual ~FEMenuEntry();
	virtual void Load();
	virtual void OnSelect();
	virtual void Highlight(bool h = true, bool anim = true);
	virtual void Disable(bool d = true);
	virtual bool GetDisable();
	virtual void Draw();
	virtual void Update(float time_inc);
	virtual void TurnOn(bool on);
	virtual void SetSpecialColor(color32 c, color32 ch);
};

class FEManager
{
public:
	char layout[0x15644];
	color32 col_info_b;
};

extern FEManager frontendmanager;

class SaveLoadFrontEnd
{
public:
	enum type
	{
		SL_SAVE,
		SL_LOAD,
		SL_DELETE,
	};

	char layout_to_highlighted[0x4c];
	FEMenuEntry* highlighted;
	char layout_to_entry[0x3294];
	FEMenuEntry* entry[3];

	void OnUnactivate(FEMenu* m);
};

void SaveLoadFrontEnd::OnUnactivate(FEMenu* m)
{
	color32 c = frontendmanager.col_info_b;

	if (!highlighted)
	{
		for(int i=0; i<3; i++)
			entry[i]->SetSpecialColor(c, c);
		return;
	}
	switch(highlighted->entry_num)
	{
	case SL_LOAD:
		c.c.a = 127;
		entry[SL_SAVE]->SetSpecialColor(c,c);

		c.c.a = 255;
		entry[SL_LOAD]->SetSpecialColor(c,c);

		c.c.a = 127;
		entry[SL_DELETE]->SetSpecialColor(c,c);
		break;

	case SL_SAVE:
		c.c.a = 127;
		entry[SL_LOAD]->SetSpecialColor(c,c);

		c.c.a = 255;
		entry[SL_SAVE]->SetSpecialColor(c,c);

		c.c.a = 127;
		entry[SL_DELETE]->SetSpecialColor(c,c);
		break;

	case SL_DELETE:
		c.c.a = 127;
		entry[SL_SAVE]->SetSpecialColor(c,c);

		c.c.a = 255;
		entry[SL_DELETE]->SetSpecialColor(c,c);

		c.c.a = 127;
		entry[SL_LOAD]->SetSpecialColor(c,c);
		break;
	}
}
